// Готовит два сообщения: английский отклик для копирования и русское объяснение
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Ответ может прийти строкой JSON или уже разобранным объектом
const getRaw = (j) => {
  if (j.text !== undefined) return j.text;
  for (const o of (j.output || [])) for (const c of (o.content || [])) if (c.text !== undefined) return c.text;
  return '';
};
const raw = getRaw($json);
let d;
try { d = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { d = { proposal_en: String(raw), proposal_ru: '(не удалось разобрать ответ ИИ)' }; }
const job = $('MARK TAKEN').item.json;
const msg1 = '🇬🇧 <b>Отклик для Upwork</b> — нажмите на текст, он скопируется:\n\n<pre>' + esc(d.proposal_en).slice(0, 3700) + '</pre>';
const msg2 = [
  '📌 <b>' + esc(job.title_ru || job.title) + '</b>',
  '🇷🇺 <b>Перевод отклика:</b>\n' + esc(d.proposal_ru),
  d.portfolio_used_ru ? '🗂 <b>Портфолио в отклике:</b> ' + esc(d.portfolio_used_ru) + '\nПри отклике на Upwork можно прикрепить этот проект из портфолио.' : '',
  d.plan_ru ? '🛠 <b>Как делать:</b>\n' + esc(d.plan_ru) : '',
  d.price_ru ? '💰 <b>Цена:</b> ' + esc(d.price_ru) : '',
  d.time_ru ? '⏱ <b>Срок:</b> ' + esc(d.time_ru) : '',
  d.difficulty_ru ? '📊 <b>Сложность:</b> ' + esc(d.difficulty_ru) : '',
  '👉 Откройте заказ, нажмите <b>Apply now</b>, вставьте отклик и укажите цену. Отправляете вы сами.',
].filter(Boolean).join('\n\n').slice(0, 4000);
return { json: { id: job.id, url: /^https?:\/\//.test(job.url || '') ? job.url : 'https://www.upwork.com/nx/find-work/', proposal_en: d.proposal_en || '', proposal_ru: d.proposal_ru || '', plan_ru: d.plan_ru || '', msg1, msg2 } };

parameters.query:
UPDATE upwork_jobs SET proposal = r.proposal_en, proposal_ru = r.proposal_ru, plan_ru = r.plan_ru
FROM json_to_record($1::json) AS r(id int, proposal_en text, proposal_ru text, plan_ru text)
WHERE upwork_jobs.id = r.id;

