  return '';
};
const raw = getRaw($json);
let d;
try { d = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { d = { direction: 'en2ru', translation: String(raw) }; }
let text;
if (d.direction === 'ru2en') {
  text = '🇬🇧 <b>Для клиента</b> — нажмите, чтобы скопировать:\n\n<pre>' + esc(d.translation) + '</pre>' + (d.back_ru ? '\n\n🔁 <b>Проверка (обратный перевод):</b>\n' + esc(d.back_ru) : '');
} else {
  text = '🇷🇺 <b>Перевод:</b>\n' + esc(d.translation) + (d.note_ru ? '\n\n💡 ' + esc(d.note_ru) : '');
}
return { json: { text: text.slice(0, 4000) } };

