// ТЗ по-русски + задание для Claude Code (уходит в очередь помощника)
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const getRaw = (j) => {
  if (j.text !== undefined) return j.text;
  for (const o of (j.output || [])) for (const c of (o.content || [])) if (c.text !== undefined) return c.text;
  return '';
};
const raw = getRaw($json);
let d;
try { d = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { d = { summary_ru: String(raw) }; }
const m = $('GET MESSAGE + JOB').item.json;
const title = String(m.job_title_full || m.job_title || ('Заказ от ' + (m.client || 'клиента'))).slice(0, 200);
const msg1 = [
  '🛠 <b>ТЗ: ' + esc(title) + '</b>',
  '📌 ' + esc(d.summary_ru),
  d.requirements_ru ? '<b>Требования:</b>\n' + esc(d.requirements_ru) : '',
  d.deliverables_ru ? '<b>Что сдать:</b>\n' + esc(d.deliverables_ru) : '',
  d.stack_ru ? '<b>Технологии:</b> ' + esc(d.stack_ru) : '',
  d.questions_en ? '❓ <b>Вопросы клиенту</b> (нажмите, чтобы скопировать):\n<pre>' + esc(d.questions_en) + '</pre>\n🔁 ' + esc(d.questions_ru) : '',
].filter(Boolean).join('\n\n').slice(0, 4000);
const prompt = [
  '# ЗАДАЧА: ' + title,
  d.claude_prompt_ru || '',
  '',
  '# ТРЕБОВАНИЯ',
  d.requirements_ru || '',
  '',
  '# ЧТО СДАТЬ',
  d.deliverables_ru || '',
  '',
  '# ТЕХНОЛОГИИ',
  d.stack_ru || '',
].join('\n');
return { json: { id: m.id, title, prompt, spec: JSON.stringify(d), msg1 } };

